import{t as e}from"./utils-COoNfFoj.js";var t={slug:`carmen-vicente`,influencerName:`Carmen Vicente`,influencerHandle:`@carmenvicente`,influencerAvatarUrl:`${e}/carmen-vicente-avatar.jpeg`,heroDescription:`After 15 years of working in social, it’s still jarring to post content and have it misinterpreted. Blind spots are inevitable when a content team is trying to hit impression goals, so I created a comprehensive tool that can pre-vet posts and scripts, rewrite suggested changes, and translate copy from one platform to another—all while keeping me informed on industry-specific news and trends.`,assetTitle:`The Troll`,screenshotUrl:`${e}/carmen-vicente.png`,remixUrl:`https://www.perplexity.ai/computer/a/the-troll-WjE8iOmQSCiOv7lo7HKlAw`,promptTitle:`Try Carmen's prompt`,promptText:`A pre-publish post-vetting tool for B2B social media managers, marketers, and executives where the troll’s job is to roast my draft before I post it—vetting for sensitivities, flagging risks, and suggesting changes I can actually use; he’s mean but he’s right. The look and feel is cute-ugly with a hand-drawn, scratchy, slightly wonky aesthetic—cream paper, charcoal ink, and tomato-red accents, with serif headlines using italic emphasis and monospace for system text, all framed in window-chrome panes like an old desktop. The troll is named Heckleton, with four facial expressions and an “angry mode” that triggers when risk is high. The core flow: I paste a draft, pick a platform, and set a severity dial (mild → scorched earth), and he reads it, returning a risk score, line-by-line critiques tied to real sensitivities, and a fixer pane with rewritten options; include an “earnest friend” button for when I want a sincere take instead of a roast, plus a platform translator (e.g., LinkedIn → X). At the top of the dashboard is Heckleton’s Brief, where every morning he delivers one headline post idea plus two backups, each with a hook, why-now angle, framework, and a starter draft I can click “Draft this” on to seed the vetting flow. Include a Notion connector where I paste a meeting page URL and integration token and he ingests the full page (including toggles) to mine it for tomorrow’s post idea, a LinkedIn winners input where I paste top-performing posts and he distills the topics, frameworks, and hook styles that work for me, and a live news cycle layer that monitors real-time events and flags posts that could land poorly given the current context.`};export{t as default};
